1	using Avalonia.RemoteControl.Protocol;
2	using Avalonia.RemoteControl.Protocol.V1;
3	using Avalonia.RemoteControl.Server.Protocol;
4	using Avalonia.RemoteControl.Server.Runtime;
5	using Avalonia.RemoteControl.Server.Security;
6	using Google.Protobuf;
7	using Microsoft.Extensions.Logging;
8	
9	namespace Avalonia.RemoteControl.Server.Bridge;
10	
11	/// <summary>
12	/// Dispatches Android bridge request envelopes to the host-independent remote-control runtime.
13	/// </summary>
14	public sealed class RemoteControlBridgeRequestHandler
15	{
16	    private readonly IRemoteControlRuntime runtime;
17	    private readonly RemoteControlBearerTokenAuthenticator authenticator;
18	    private readonly ILogger<RemoteControlBridgeRequestHandler> logger;
19	
20	    /// <summary>
21	    /// Initializes a new instance of the <see cref="RemoteControlBridgeRequestHandler"/> class.
22	    /// </summary>
23	    /// <param name="runtime">Transport-independent runtime service.</param>
24	    /// <param name="authenticator">Bearer token authenticator.</param>
25	    /// <param name="logger">Bridge logger.</param>
26	    public RemoteControlBridgeRequestHandler(
27	        IRemoteControlRuntime runtime,
28	        RemoteControlBearerTokenAuthenticator authenticator,
29	        ILogger<RemoteControlBridgeRequestHandler> logger)
30	    {
31	        this.runtime = runtime;
32	        this.authenticator = authenticator;
33	        this.logger = logger;
34	    }
35	
36	    /// <summary>
37	    /// Handles a single bridge request envelope.
38	    /// </summary>
39	    /// <param name="request">Bridge request envelope.</param>
40	    /// <param name="cancellationToken">Cancellation token.</param>
41	    /// <returns>A bridge response envelope.</returns>
42	    public async ValueTask<BridgeResponse> HandleAsync(
43	        BridgeRequest request,
44	        CancellationToken cancellationToken = default)
45	    {
46	        ArgumentNullException.ThrowIfNull(request);
47	
48	        if (!string.Equals(
49	            request.ProtocolVersion,
50	            RemoteControlProtocol.DisplayVersion,
51	            StringComparison.Ordinal))
52	        {
53	            return Failure(
54	                request,
55	                BridgeStatus.Unsupported,
56	                "Unsupported bridge protocol version.");
57	        }
58	
59	        var auth = authenticator.AuthenticateAuthorization(request.Authorization);
60	        if (!auth.IsAuthenticated)
61	        {
62	            return Failure(request, BridgeStatus.Unauthenticated, auth.FailureMessage);
63	        }
64	
65	        try
66	        {
67	            return request.Method switch
68	            {
69	                BridgeMethod.GetCapabilities => HandleGetCapabilities(request, auth.ClientIdentity),
70	                BridgeMethod.GetSnapshot => await HandleGetSnapshotAsync(request, cancellationToken).ConfigureAwait(false),
71	                BridgeMethod.InvokeClick => await HandleInvokeClickAsync(request, auth.ClientIdentity, cancellationToken).ConfigureAwait(false),
72	                BridgeMethod.InvokeFocus => await HandleInvokeFocusAsync(request, auth.ClientIdentity, cancellationToken).ConfigureAwait(false),
73	                BridgeMethod.SetProperty => await HandleSetPropertyAsync(request, auth.ClientIdentity, cancellationToken).ConfigureAwait(false),
74	                BridgeMethod.SendInput => await HandleSendInputAsync(request, auth.ClientIdentity, cancellationToken).ConfigureAwait(false),
75	                BridgeMethod.WatchTree or BridgeMethod.WatchFrames or BridgeMethod.WatchLogs => Failure(
76	                    request,
77	                    BridgeStatus.Unsupported,
78	                    "Bridge streaming must be read through a streaming bridge connection."),
79	                _ => Failure(request, BridgeStatus.Unsupported, "Unsupported bridge method."),
80	            };
81	        }
82	        catch (InvalidProtocolBufferException)
83	        {
84	            return Failure(request, BridgeStatus.Error, "Invalid bridge payload.");
85	        }
86	        catch (RemoteControlRuntimeException exception)
87	        {
88	            return Failure(request, ToBridgeStatus(exception.ErrorCode), exception.Message);
89	        }
90	        catch (OperationCanceledException)
91	        {
92	            return Failure(request, BridgeStatus.Cancelled, "Bridge request was cancelled.");
93	        }
94	        catch (Exception exception)
95	        {
96	            logger.LogError(
97	                exception,
98	                "Bridge request {RequestId} failed for method {Method}.",
99	                request.RequestId,
100	                request.Method);
101	
102	            return Failure(request, BridgeStatus.Error, "Bridge request failed.");
103	        }
104	    }
105	
106	    /// <summary>
107	    /// Handles a bridge request as a potentially long-lived response stream.
108	    /// </summary>
109	    /// <param name="request">Bridge request envelope.</param>
110	    /// <param name="cancellationToken">Cancellation token.</param>
111	    /// <returns>Response envelopes.</returns>
112	    public async IAsyncEnumerable<BridgeResponse> HandleResponsesAsync(
113	        BridgeRequest request,
114	        [System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken cancellationToken = default)
115	    {
116	        if (request.Method is not (BridgeMethod.WatchTree or BridgeMethod.WatchFrames or BridgeMethod.WatchLogs))
117	        {
118	            yield return await HandleAsync(request, cancellationToken).ConfigureAwait(false);
119	            yield break;
120	        }
121	
122	        if (!string.Equals(
123	            request.ProtocolVersion,
124	            RemoteControlProtocol.DisplayVersion,
125	            StringComparison.Ordinal))
126	        {
127	            yield return Failure(request, BridgeStatus.Unsupported, "Unsupported bridge protocol version.");
128	            yield break;
129	        }
130	
131	        var auth = authenticator.AuthenticateAuthorization(request.Authorization);
132	        if (!auth.IsAuthenticated)
133	        {
134	            yield return Failure(request, BridgeStatus.Unauthenticated, auth.FailureMessage);
135	            yield break;
136	        }
137	
138	        var stream = CreateStreamPayloadsAsync(request, cancellationToken);
139	        await using var enumerator = stream.GetAsyncEnumerator(cancellationToken);
140	
141	        while (true)
142	        {
143	            BridgeResponse? failure = null;
144	            var hasNext = false;
145	
146	            try
147	            {
148	                hasNext = await enumerator.MoveNextAsync().ConfigureAwait(false);
149	            }
