1	using System.Net;
2	using System.Net.Sockets;
3	using Avalonia.RemoteControl.Protocol;
4	using Avalonia.RemoteControl.Protocol.V1;
5	using Microsoft.Extensions.Logging;
6	using Microsoft.Extensions.Options;
7	
8	namespace Avalonia.RemoteControl.Server.Bridge;
9	
10	/// <summary>
11	/// Hosts the Android-compatible bridge protocol over a loopback TCP listener.
12	/// </summary>
13	public sealed class RemoteControlBridgeTcpListener : IAsyncDisposable
14	{
15	    private readonly RemoteControlBridgeRequestHandler requestHandler;
16	    private readonly AvaloniaRemoteControlOptions options;
17	    private readonly ILogger<RemoteControlBridgeTcpListener> logger;
18	    private readonly object sync = new();
19	    private readonly HashSet<Task> clientTasks = [];
20	
21	    private TcpListener? tcpListener;
22	    private CancellationTokenSource? stopSource;
23	    private Task? acceptLoopTask;
24	
25	    /// <summary>
26	    /// Initializes a new instance of the <see cref="RemoteControlBridgeTcpListener"/> class.
27	    /// </summary>
28	    /// <param name="requestHandler">Bridge request handler.</param>
29	    /// <param name="options">Remote-control options.</param>
30	    /// <param name="logger">Listener logger.</param>
31	    public RemoteControlBridgeTcpListener(
32	        RemoteControlBridgeRequestHandler requestHandler,
33	        IOptions<AvaloniaRemoteControlOptions> options,
34	        ILogger<RemoteControlBridgeTcpListener> logger)
35	    {
36	        ArgumentNullException.ThrowIfNull(requestHandler);
37	        ArgumentNullException.ThrowIfNull(options);
38	        ArgumentNullException.ThrowIfNull(logger);
39	
40	        this.requestHandler = requestHandler;
41	        this.options = options.Value;
42	        this.logger = logger;
43	    }
44	
45	    /// <summary>
46	    /// Gets the bound loopback endpoint after the listener starts.
47	    /// </summary>
48	    public IPEndPoint? BoundEndpoint { get; private set; }
49	
50	    /// <summary>
51	    /// Gets a value indicating whether the listener is running.
52	    /// </summary>
53	    public bool IsRunning
54	    {
55	        get
56	        {
57	            lock (sync)
58	            {
59	                return tcpListener is not null;
60	            }
61	        }
62	    }
63	
64	    /// <summary>
65	    /// Starts the loopback TCP listener.
66	    /// </summary>
67	    /// <param name="cancellationToken">Cancellation token.</param>
68	    /// <returns>A task that completes once the listener has been started.</returns>
69	    public Task StartAsync(CancellationToken cancellationToken = default)
70	    {
71	        cancellationToken.ThrowIfCancellationRequested();
72	        ValidateStartupOptions();
73	
74	        lock (sync)
75	        {
76	            if (tcpListener is not null)
77	            {
78	                return Task.CompletedTask;
79	            }
80	
81	            stopSource = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
82	            tcpListener = new TcpListener(IPAddress.Loopback, options.Port);
83	            tcpListener.Start();
84	            BoundEndpoint = (IPEndPoint)tcpListener.LocalEndpoint;
85	            acceptLoopTask = AcceptLoopAsync(tcpListener, stopSource.Token);
86	        }
87	
88	        logger.LogInformation(
89	            "Avalonia remote-control bridge listener started on loopback port {Port}.",
90	            BoundEndpoint!.Port);
91	
92	        return Task.CompletedTask;
93	    }
94	
95	    /// <summary>
96	    /// Stops the loopback TCP listener and waits for in-flight bridge requests to finish.
97	    /// </summary>
98	    /// <param name="cancellationToken">Cancellation token.</param>
99	    /// <returns>A task representing the stop operation.</returns>
100	    public async Task StopAsync(CancellationToken cancellationToken = default)
101	    {
102	        TcpListener? listener;
103	        CancellationTokenSource? source;
104	        Task? acceptLoop;
105	
106	        lock (sync)
107	        {
108	            listener = tcpListener;
109	            source = stopSource;
110	            acceptLoop = acceptLoopTask;
111	
112	            tcpListener = null;
113	            stopSource = null;
114	            acceptLoopTask = null;
115	            BoundEndpoint = null;
116	        }
117	
118	        if (listener is null)
119	        {
120	            return;
121	        }
122	
123	        source?.Cancel();
124	        listener.Stop();
125	
126	        if (acceptLoop is not null)
127	        {
128	            await WaitWithoutCancellationAsync(acceptLoop).ConfigureAwait(false);
129	        }
130	
131	        Task[] pendingClients;
132	        lock (sync)
133	        {
134	            pendingClients = [.. clientTasks];
135	        }
136	
137	        if (pendingClients.Length > 0)
138	        {
139	            await Task.WhenAll(pendingClients).WaitAsync(cancellationToken).ConfigureAwait(false);
140	        }
141	
142	        source?.Dispose();
143	        logger.LogInformation("Avalonia remote-control bridge listener stopped.");
144	    }
145	
146	    /// <summary>
147	    /// Creates marker metadata for the currently bound endpoint.
148	    /// </summary>
149	    /// <returns>Endpoint marker metadata.</returns>
150	    public RemoteControlBridgeEndpointMarker CreateEndpointMarker()
151	    {
152	        var endpoint = BoundEndpoint
153	            ?? throw new InvalidOperationException("Bridge listener must be started before creating a marker.");
154	
155	        var token = options.AuthenticationToken
156	            ?? throw new InvalidOperationException("Bridge authentication token is not configured.");
157	
158	        return RemoteControlBridgeEndpointMarker.Create(endpoint.Port, token);
159	    }
160	
161	    /// <inheritdoc />
162	    public async ValueTask DisposeAsync()
163	    {
164	        await StopAsync().ConfigureAwait(false);
165	    }
166	
167	    private async Task AcceptLoopAsync(
168	        TcpListener listener,
169	        CancellationToken cancellationToken)
170	    {
171	        try
172	        {
173	            while (!cancellationToken.IsCancellationRequested)
174	            {
175	                var client = await listener.AcceptTcpClientAsync(cancellationToken).ConfigureAwait(false);
176	                logger.LogDebug(
177	                    "Bridge TCP client accepted from {RemoteEndPoint}.",
178	                    client.Client.RemoteEndPoint?.ToString() ?? "unknown");
179	                var clientTask = HandleClientAsync(client, cancellationToken);
180	                TrackClientTask(clientTask);
181	            }
182	        }
183	        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
184	        {
185	        }
186	        catch (ObjectDisposedException) when (cancellationToken.IsCancellationRequested)
187	        {
188	        }
189	        catch (SocketException) when (cancellationToken.IsCancellationRequested)
190	        {
191	        }
192	        catch (Exception exception)
193	        {
194	            logger.LogError(exception, "Avalonia remote-control bridge listener failed.");
195	        }
196	    }
197	
198	    private async Task HandleClientAsync(
199	        TcpClient client,
200	        CancellationToken cancellationToken)
201	    {
202	        using (client)
203	        {
204	            try
205	            {
206	                await using var stream = client.GetStream();
207	                var request = await BridgeFrameCodec.ReadAsync(
208	                    stream,
209	                    BridgeRequest.Parser,
210	                    cancellationToken: cancellationToken).ConfigureAwait(false);
