1	PRAGMA foreign_keys=ON;
2	PRAGMA user_version=1;
3	CREATE TABLE catalog_meta(key TEXT NOT NULL PRIMARY KEY,value TEXT NOT NULL);
4	CREATE TABLE sources(source_id TEXT NOT NULL PRIMARY KEY, path TEXT NOT NULL, url TEXT NOT NULL, revision TEXT NOT NULL, retrieved_at TEXT NOT NULL, sha256 TEXT NOT NULL CHECK((length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*')), api_level INTEGER, channel TEXT NOT NULL, kind TEXT NOT NULL, license TEXT NOT NULL);
5	CREATE TABLE bindings(binding_id TEXT NOT NULL PRIMARY KEY CHECK((length(binding_id)=64 AND binding_id NOT GLOB '*[^0-9a-f]*')), signature TEXT NOT NULL UNIQUE, package TEXT NOT NULL, owner TEXT, kind TEXT NOT NULL, name TEXT NOT NULL, return_type TEXT, arguments_json TEXT, raw_signature TEXT NOT NULL, codec_status TEXT NOT NULL DEFAULT 'unknown');
6	CREATE INDEX binding_lookup ON bindings(package,owner,name,binding_id);
7	CREATE TABLE occurrences(binding_id TEXT NOT NULL REFERENCES bindings, source_id TEXT NOT NULL REFERENCES sources, line INTEGER NOT NULL, PRIMARY KEY(binding_id,source_id,line));
8	CREATE TABLE binding_declarations(binding_id TEXT NOT NULL,source_id TEXT NOT NULL,line INTEGER NOT NULL,document_json TEXT NOT NULL,PRIMARY KEY(binding_id,source_id,line),FOREIGN KEY(binding_id,source_id,line) REFERENCES occurrences);
9	CREATE TABLE permission_definitions(name TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources, protection_level TEXT, attributes_json TEXT NOT NULL, PRIMARY KEY(name,source_id));
10	CREATE TABLE permission_relations(id INTEGER PRIMARY KEY,binding_id TEXT NOT NULL REFERENCES bindings,source_id TEXT NOT NULL REFERENCES sources,line INTEGER NOT NULL,annotation TEXT,logic TEXT NOT NULL CHECK(logic IN ('all','any','permission','access','conditional','manual','explicit-none','unknown')),expression_json TEXT NOT NULL,raw_annotation TEXT);
11	CREATE INDEX permission_lookup ON permission_relations(binding_id);
12	CREATE TABLE aidl_schemas(source_id TEXT NOT NULL PRIMARY KEY REFERENCES sources, package TEXT, descriptor TEXT, declaration_kind TEXT, raw_schema TEXT NOT NULL, parse_status TEXT NOT NULL, transaction_metadata_json TEXT NOT NULL, codec_status TEXT NOT NULL);
13	CREATE TABLE issues(id INTEGER PRIMARY KEY, source_id TEXT REFERENCES sources,line INTEGER,category TEXT NOT NULL,reason TEXT NOT NULL,raw TEXT);
14	-- Contract 1.0.0: source records are append-only. Imports run in one transaction.
15	CREATE TRIGGER sources_immutable_update BEFORE UPDATE ON sources BEGIN SELECT RAISE(ABORT,'Imported sources are immutable'); END;
16	CREATE TRIGGER sources_immutable_delete BEFORE DELETE ON sources BEGIN SELECT RAISE(ABORT,'Imported sources are immutable'); END;
17	CREATE TRIGGER bindings_immutable_update BEFORE UPDATE ON bindings BEGIN SELECT RAISE(ABORT,'Imported bindings are immutable'); END;
18	CREATE TRIGGER bindings_immutable_delete BEFORE DELETE ON bindings BEGIN SELECT RAISE(ABORT,'Suppress imported records using a local overlay'); END;
19	CREATE TABLE registries(registry_id TEXT NOT NULL PRIMARY KEY, registry_version INTEGER NOT NULL UNIQUE CHECK(registry_version>=1), schema_version TEXT NOT NULL, android_version TEXT NOT NULL, api_level INTEGER, source_set_hash TEXT NOT NULL, created_at TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('staged','validated','rejected','published','retired')), validation_json TEXT NOT NULL,UNIQUE(registry_id,state));
20	CREATE TABLE registry_sources(registry_id TEXT NOT NULL REFERENCES registries,source_id TEXT NOT NULL REFERENCES sources,PRIMARY KEY(registry_id,source_id));
21	CREATE TABLE active_registry(singleton INTEGER PRIMARY KEY CHECK(singleton=1),registry_id TEXT NOT NULL REFERENCES registries,published_state TEXT GENERATED ALWAYS AS ('published') VIRTUAL,FOREIGN KEY(registry_id,published_state) REFERENCES registries(registry_id,state) DEFERRABLE INITIALLY DEFERRED);
22	CREATE TABLE overlays(entry_id TEXT NOT NULL PRIMARY KEY CHECK(length(entry_id)=64 AND entry_id NOT GLOB '*[^0-9a-f]*'), imported_binding_id TEXT REFERENCES bindings, canonical_signature TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), base_registry_id TEXT REFERENCES registries, base_record_hash TEXT CHECK(base_record_hash IS NULL OR (length(base_record_hash)=64 AND base_record_hash NOT GLOB '*[^0-9a-f]*')), state TEXT NOT NULL CHECK(state IN ('active','suppressed','conflict','deleted')), document_json TEXT NOT NULL CHECK(json_valid(document_json)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL,FOREIGN KEY(entry_id,revision) REFERENCES entry_history(entry_id,revision) DEFERRABLE INITIALLY DEFERRED,CHECK(imported_binding_id IS NULL OR entry_id=imported_binding_id),CHECK(state<>'suppressed' OR imported_binding_id IS NOT NULL),CHECK(state<>'deleted' OR imported_binding_id IS NULL));
23	CREATE INDEX overlay_lookup ON overlays(imported_binding_id,state);
24	CREATE UNIQUE INDEX overlay_one_import ON overlays(imported_binding_id) WHERE imported_binding_id IS NOT NULL;
25	CREATE TABLE entry_history(entry_id TEXT NOT NULL REFERENCES overlays, revision INTEGER NOT NULL, operation TEXT NOT NULL CHECK(operation IN ('create','update','suppress','delete','restore','rebase','conflict')), document_json TEXT NOT NULL CHECK(json_valid(document_json)), actor TEXT NOT NULL, occurred_at TEXT NOT NULL, PRIMARY KEY(entry_id,revision));
26	CREATE TRIGGER history_immutable_update BEFORE UPDATE ON entry_history BEGIN SELECT RAISE(ABORT,'History is append-only'); END;
27	CREATE TRIGGER history_immutable_delete BEFORE DELETE ON entry_history BEGIN SELECT RAISE(ABORT,'History is append-only'); END;
28	CREATE TABLE legacy_import_jobs(idempotency_key TEXT NOT NULL PRIMARY KEY,request_sha256 TEXT NOT NULL,registry_id TEXT REFERENCES registries,state TEXT NOT NULL CHECK(state IN ('staged','validated','rejected','published','retired')),result_json TEXT NOT NULL);
29	-- Bounded effective-view readers select current registry then join occurrences,
30	-- registry_sources and overlays. They MUST exclude suppressed/deleted/conflict
31	-- rows for invocation discovery and reject unknown semantic extensions.
32	
33	CREATE TRIGGER occurrences_immutable_update BEFORE UPDATE ON occurrences BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
34	
35	CREATE TRIGGER occurrences_immutable_delete BEFORE DELETE ON occurrences BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
36	
37	CREATE TRIGGER binding_declarations_immutable_update BEFORE UPDATE ON binding_declarations BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
38	
39	CREATE TRIGGER binding_declarations_immutable_delete BEFORE DELETE ON binding_declarations BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
40	
41	CREATE TRIGGER permission_definitions_immutable_update BEFORE UPDATE ON permission_definitions BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
42	
43	CREATE TRIGGER permission_definitions_immutable_delete BEFORE DELETE ON permission_definitions BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
44	
45	CREATE TRIGGER permission_relations_immutable_update BEFORE UPDATE ON permission_relations BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
46	
47	CREATE TRIGGER permission_relations_immutable_delete BEFORE DELETE ON permission_relations BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
48	
49	CREATE TRIGGER aidl_schemas_immutable_update BEFORE UPDATE ON aidl_schemas BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
50	
51	CREATE TRIGGER aidl_schemas_immutable_delete BEFORE DELETE ON aidl_schemas BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
52	
53	CREATE TRIGGER issues_immutable_update BEFORE UPDATE ON issues BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
54	
55	CREATE TRIGGER issues_immutable_delete BEFORE DELETE ON issues BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
56	
57	CREATE TRIGGER registry_sources_immutable_update BEFORE UPDATE ON registry_sources BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
58	
59	CREATE TRIGGER registry_sources_immutable_delete BEFORE DELETE ON registry_sources BEGIN SELECT RAISE(ABORT,'Imported source records are append-only'); END;
60	
61	CREATE TRIGGER registry_state_transition BEFORE UPDATE OF state ON registries
62	 WHEN new.state<>old.state AND NOT ((old.state='staged' AND new.state IN ('validated','rejected')) OR (old.state='validated' AND new.state='published') OR (old.state='published' AND new.state='retired'))
63	 BEGIN SELECT RAISE(ABORT,'Invalid registry state transition'); END;
64	
65	CREATE TABLE idempotency_records(principal TEXT NOT NULL,operation TEXT NOT NULL,idempotency_key TEXT NOT NULL,request_sha256 TEXT NOT NULL CHECK(length(request_sha256)=64),response_status INTEGER NOT NULL CHECK(response_status BETWEEN 100 AND 599),response_json TEXT NOT NULL CHECK(json_valid(response_json)),resource_id TEXT NOT NULL,PRIMARY KEY(principal,operation,idempotency_key));
66	CREATE TABLE registry_events(event_id TEXT NOT NULL PRIMARY KEY,actor TEXT NOT NULL,request_id TEXT NOT NULL,registry_id TEXT NOT NULL REFERENCES registries,kind TEXT NOT NULL,occurred_at TEXT NOT NULL,result_json TEXT NOT NULL CHECK(json_valid(result_json)));
67	CREATE TABLE registry_outbox(event_id TEXT NOT NULL PRIMARY KEY REFERENCES registry_events,affected_entry_ids_json TEXT NOT NULL CHECK(json_valid(affected_entry_ids_json)),delivered_at TEXT);
68	CREATE TRIGGER registry_events_no_update BEFORE UPDATE ON registry_events BEGIN SELECT RAISE(ABORT,'Registry events are append-only'); END;
69	CREATE TRIGGER registry_events_no_delete BEFORE DELETE ON registry_events BEGIN SELECT RAISE(ABORT,'Registry events are append-only'); END;
70	CREATE TRIGGER overlay_revision_update BEFORE UPDATE ON overlays WHEN new.revision<=old.revision BEGIN SELECT RAISE(ABORT,'Every overlay write increments revision'); END;
71	CREATE TRIGGER overlay_canonical_insert BEFORE INSERT ON overlays WHEN new.imported_binding_id IS NOT NULL AND new.canonical_signature<>(SELECT signature FROM bindings WHERE binding_id=new.imported_binding_id) BEGIN SELECT RAISE(ABORT,'Imported identity/signature mismatch'); END;
72	CREATE TRIGGER overlay_canonical_update BEFORE UPDATE ON overlays WHEN new.entry_id<>old.entry_id OR new.canonical_signature<>old.canonical_signature OR (new.imported_binding_id IS NOT NULL AND new.canonical_signature<>(SELECT signature FROM bindings WHERE binding_id=new.imported_binding_id)) BEGIN SELECT RAISE(ABORT,'Canonical identity cannot change'); END;
73	
74	CREATE UNIQUE INDEX registries_one_published ON registries(state) WHERE state='published';
75	CREATE TRIGGER active_must_be_published_insert BEFORE INSERT ON active_registry WHEN (SELECT state FROM registries WHERE registry_id=new.registry_id) IS NOT 'published' BEGIN SELECT RAISE(ABORT,'Active registry must be published'); END;
76	CREATE TRIGGER active_must_be_published_update BEFORE UPDATE OF registry_id ON active_registry WHEN (SELECT state FROM registries WHERE registry_id=new.registry_id) IS NOT 'published' OR (new.registry_id<>old.registry_id AND (SELECT registry_version FROM registries WHERE registry_id=new.registry_id)<=(SELECT registry_version FROM registries WHERE registry_id=old.registry_id)) BEGIN SELECT RAISE(ABORT,'Publication requires a newer published registry'); END;
77	-- Storage baseline v3: Entry1.0 base plus documented1.1 AIDL type kinds;
78	-- unknown semantic vocabulary is rejected/quarantined, never granted authority.
79	PRAGMA foreign_keys=ON;
80	BEGIN IMMEDIATE;
81	CREATE TABLE source_details(source_id TEXT NOT NULL PRIMARY KEY REFERENCES sources, document_json TEXT NOT NULL CHECK(json_valid(document_json)));
82	CREATE TABLE parse_reports(source_id TEXT NOT NULL PRIMARY KEY REFERENCES sources, document_json TEXT NOT NULL CHECK(json_valid(document_json)));
83	ALTER TABLE binding_declarations ADD COLUMN record_sha256 TEXT;
84	CREATE TABLE annotation_evidence(source_id TEXT NOT NULL REFERENCES sources, locator TEXT NOT NULL, binding_id TEXT REFERENCES bindings, scope TEXT NOT NULL, document_json TEXT NOT NULL CHECK(json_valid(document_json)), PRIMARY KEY(source_id,locator));
85	CREATE INDEX annotation_target ON annotation_evidence(binding_id);
86	CREATE TABLE permission_symbols(symbol TEXT NOT NULL, value TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources, line INTEGER NOT NULL, PRIMARY KEY(symbol,source_id,line));
87	CREATE TABLE registry_entries(registry_id TEXT NOT NULL REFERENCES registries,entry_id TEXT NOT NULL REFERENCES bindings(binding_id),document_json TEXT NOT NULL CHECK(json_valid(document_json)),record_sha256 TEXT NOT NULL CHECK(length(record_sha256)=64 AND record_sha256 NOT GLOB '*[^0-9a-f]*'),PRIMARY KEY(registry_id,entry_id));
88	CREATE TRIGGER source_details_no_update BEFORE UPDATE ON source_details BEGIN SELECT RAISE(ABORT,'Imported evidence is immutable'); END;
89	CREATE TRIGGER source_details_no_delete BEFORE DELETE ON source_details BEGIN SELECT RAISE(ABORT,'Imported evidence is immutable'); END;
90	CREATE TRIGGER annotation_evidence_no_update BEFORE UPDATE ON annotation_evidence BEGIN SELECT RAISE(ABORT,'Imported evidence is immutable'); END;
91	CREATE TRIGGER annotation_evidence_no_delete BEFORE DELETE ON annotation_evidence BEGIN SELECT RAISE(ABORT,'Imported evidence is immutable'); END;
92	CREATE TRIGGER permission_symbols_no_update BEFORE UPDATE ON permission_symbols BEGIN SELECT RAISE(ABORT,'Imported evidence is immutable'); END;
93	CREATE TRIGGER permission_symbols_no_delete BEFORE DELETE ON permission_symbols BEGIN SELECT RAISE(ABORT,'Imported evidence is immutable'); END;
94	CREATE TRIGGER registry_entries_no_update BEFORE UPDATE ON registry_entries BEGIN SELECT RAISE(ABORT,'Publish a new registry instead'); END;
95	CREATE TRIGGER registry_entries_no_delete BEFORE DELETE ON registry_entries BEGIN SELECT RAISE(ABORT,'Publish a new registry instead'); END;
96	-- ETag composition is identical for base, overlay, tombstone and history CAS.
97	CREATE TABLE catalog_view(singleton INTEGER PRIMARY KEY CHECK(singleton=1),registry_generation INTEGER NOT NULL CHECK(registry_generation>0),overlay_generation INTEGER NOT NULL CHECK(overlay_generation>=0));
98	INSERT INTO catalog_view VALUES(1,1,0);
99	CREATE TRIGGER overlay_generation_insert AFTER INSERT ON overlays BEGIN UPDATE catalog_view SET overlay_generation=overlay_generation+1; END;
100	CREATE TRIGGER overlay_generation_update AFTER UPDATE ON overlays BEGIN UPDATE catalog_view SET overlay_generation=overlay_generation+1; END;
101	CREATE TRIGGER overlay_generation_delete AFTER DELETE ON overlays BEGIN UPDATE catalog_view SET overlay_generation=overlay_generation+1; END;
102	CREATE TRIGGER registry_generation_switch AFTER UPDATE OF registry_id ON active_registry WHEN old.registry_id<>new.registry_id BEGIN UPDATE catalog_view SET registry_generation=max(registry_generation+1,(SELECT registry_version FROM registries WHERE registry_id=new.registry_id)); END;
103	CREATE TRIGGER parse_reports_no_update BEFORE UPDATE ON parse_reports BEGIN SELECT RAISE(ABORT,'Imported reports are immutable'); END;
104	CREATE TRIGGER parse_reports_no_delete BEFORE DELETE ON parse_reports BEGIN SELECT RAISE(ABORT,'Imported reports are immutable'); END;
105	CREATE TRIGGER registry_generation_initial AFTER INSERT ON active_registry BEGIN UPDATE catalog_view SET registry_generation=max(registry_generation,(SELECT registry_version FROM registries WHERE registry_id=new.registry_id)); END;
106	CREATE VIEW effective_entries AS
107	 SELECT e.entry_id,e.document_json,e.record_sha256,
108	 '"cat1:'||v.registry_generation||':'||e.record_sha256||':'||e.entry_id||':0:active"' AS etag
109	 FROM registry_entries e JOIN active_registry a ON a.registry_id=e.registry_id CROSS JOIN catalog_view v;
110	CREATE VIEW runtime_catalog AS
111	 SELECT e.entry_id,coalesce(o.document_json,e.document_json) AS document_json,
112	 '"cat1:'||v.registry_generation||':'||e.record_sha256||':'||e.entry_id||':'||coalesce(o.revision,0)||':'||coalesce(o.state,'active')||'"' AS etag
113	 FROM effective_entries e CROSS JOIN catalog_view v LEFT JOIN overlays o ON o.entry_id=e.entry_id
114	 WHERE o.entry_id IS NULL OR o.state='active'
115	 UNION ALL
116	 SELECT o.entry_id,o.document_json,'"cat1:'||v.registry_generation||':local:'||o.entry_id||':'||o.revision||':'||o.state||'"'
