CREATE TRIGGER overlay_base_current_update BEFORE UPDATE ON overlays WHEN new.imported_binding_id IS NOT NULL AND new.state IN ('active','suppressed') AND NOT EXISTS(SELECT 1 FROM effective_entries e WHERE e.entry_id=new.imported_binding_id AND e.record_sha256=new.base_record_hash) BEGIN SELECT RAISE(ABORT,'Imported overlay base must match active entry'); END;
