87	CREATE TRIGGER wire_proof_no_update BEFORE UPDATE ON binding_wire_contracts BEGIN SELECT RAISE(ABORT,'Version wire evidence rather than rewriting it'); END;
88	CREATE TRIGGER wire_proof_no_delete BEFORE DELETE ON binding_wire_contracts BEGIN SELECT RAISE(ABORT,'Retain wire evidence while versioned'); END;
89	CREATE TRIGGER device_facts_current BEFORE INSERT ON device_capability_facts WHEN NOT EXISTS(SELECT 1 FROM device_view_active a JOIN device_view_scopes s USING(scope_id) WHERE a.scope_id=new.scope_id AND a.capability_epoch=new.capability_epoch AND json_extract(new.document_json,'$.capability_epoch')=new.capability_epoch AND json_extract(new.document_json,'$.observed_at')=new.observed_at AND json_extract(new.document_json,'$.profile_id')=s.profile_id AND json_extract(new.document_json,'$.target_key')=s.target_key AND json_extract(new.document_json,'$.android_user_id')=s.android_user_id AND json_extract(new.document_json,'$.backend_instance_id')=s.backend_instance_id AND json_extract(new.document_json,'$.device_instance_id')=s.device_instance_id) BEGIN SELECT RAISE(ABORT,'Captured facts scope or epoch mismatch'); END;
90	CREATE TRIGGER device_view_stage BEFORE INSERT ON device_views WHEN new.state<>'staged' OR NOT EXISTS(SELECT 1 FROM device_view_active a WHERE a.scope_id=new.scope_id AND new.capability_epoch=a.capability_epoch AND new.view_generation=a.generation+1 AND new.registry_id=a.registry_id AND new.catalog_generation=a.catalog_generation AND new.overlay_generation=a.overlay_generation AND new.inventory_count=a.expected_inventory_count AND new.inventory_sha256=a.inventory_sha256) BEGIN SELECT RAISE(ABORT,'Stage must pin the complete current inventory and epoch'); END;
91	CREATE TRIGGER device_entry_document_consistent BEFORE INSERT ON device_view_entries WHEN json_extract(new.document_json,'$.entry_id') IS NOT new.entry_id OR json_extract(new.document_json,'$.entity_kind') IS NOT new.entity_kind OR json_extract(new.document_json,'$.state') IS NOT new.state OR json_type(new.document_json,'$.schema_hash') IS NULL OR json_extract(new.document_json,'$.schema_hash') IS NOT new.schema_hash OR json_type(new.document_json,'$.contract_hash') IS NULL OR json_extract(new.document_json,'$.contract_hash') IS NOT new.contract_hash OR json_type(new.document_json,'$.graph_digest') IS NULL OR json_extract(new.document_json,'$.graph_digest') IS NOT new.graph_digest OR json(json_extract(new.document_json,'$.reason_codes')) IS NOT json(new.reason_codes_json) OR json(json_extract(new.document_json,'$.dependencies')) IS NOT json(new.dependencies_json) OR EXISTS(SELECT 1 FROM json_each(new.reason_codes_json) WHERE type<>'text' OR length(value)=0) BEGIN SELECT RAISE(ABORT,'Device entry JSON disagrees with authoritative columns'); END;
92	CREATE TRIGGER device_header_document_consistent BEFORE INSERT ON device_views WHEN json_extract(new.document_json,'$.schema_version') IS NOT '3.0.0' OR json_extract(new.document_json,'$.view_id') IS NOT new.view_id OR json_extract(new.document_json,'$.facts_id') IS NOT new.facts_id OR json_extract(new.document_json,'$.registry_id') IS NOT new.registry_id OR json_extract(new.document_json,'$.catalog_generation') IS NOT new.catalog_generation OR json_extract(new.document_json,'$.overlay_generation') IS NOT new.overlay_generation OR json_extract(new.document_json,'$.capability_epoch') IS NOT new.capability_epoch OR json_extract(new.document_json,'$.view_generation') IS NOT new.view_generation OR json_extract(new.document_json,'$.inventory_count') IS NOT new.inventory_count OR json_extract(new.document_json,'$.inventory_sha256') IS NOT new.inventory_sha256 OR json_type(new.document_json,'$.entries') IS NOT NULL BEGIN SELECT RAISE(ABORT,'Device header JSON disagrees with immutable metadata'); END;
93	
94	CREATE TRIGGER device_active_inventory_pin BEFORE INSERT ON device_view_active WHEN NOT EXISTS(SELECT 1 FROM device_inventory_sets i WHERE i.inventory_sha256=new.inventory_sha256 AND i.state='sealed' AND i.entry_count=new.expected_inventory_count) BEGIN SELECT RAISE(ABORT,'Active scope requires verified sealed inventory'); END;
95	CREATE TRIGGER device_active_inventory_repin BEFORE UPDATE ON device_view_active WHEN NOT EXISTS(SELECT 1 FROM device_inventory_sets i WHERE i.inventory_sha256=new.inventory_sha256 AND i.state='sealed' AND i.entry_count=new.expected_inventory_count) BEGIN SELECT RAISE(ABORT,'Active scope requires verified sealed inventory'); END;
96	CREATE TRIGGER device_entry_inventory_member BEFORE INSERT ON device_view_entries WHEN NOT EXISTS(SELECT 1 FROM device_views v JOIN device_inventory_members m ON m.inventory_sha256=v.inventory_sha256 WHERE v.view_id=new.view_id AND m.entry_id=new.entry_id AND m.entity_kind=new.entity_kind AND coalesce(json_extract(m.document_json,'$.catalog_state'),'active')=json_extract(new.document_json,'$.catalog_state') AND coalesce(json_extract(m.document_json,'$.catalog_revision'),0)=json_extract(new.document_json,'$.catalog_revision') AND (json_extract(m.document_json,'$.catalog_document_sha256') IS json_extract(new.document_json,'$.catalog_document_sha256')) AND json_type(new.document_json,'$.catalog_document_sha256') IS NOT NULL AND (new.state<>'available' OR (json_type(new.document_json,'$.catalog_document_sha256')='text' AND length(json_extract(new.document_json,'$.catalog_document_sha256'))=64 AND json_extract(new.document_json,'$.catalog_document_sha256') NOT GLOB '*[^0-9a-f]*')) AND (new.state<>'available' OR EXISTS(SELECT 1 FROM json_each(m.document_json,'$.variants') variant WHERE json_extract(variant.value,'$.schema_hash')=new.contract_hash AND json_array_length(json_extract(variant.value,'$.dependencies'))=json_array_length(new.dependencies_json) AND NOT EXISTS(SELECT 1 FROM json_each(new.dependencies_json) d WHERE NOT EXISTS(SELECT 1 FROM json_each(variant.value,'$.dependencies') expected WHERE json_extract(expected.value,'$.entry_id')=json_extract(d.value,'$.entry_id') AND json_extract(expected.value,'$.schema_hash')=json_extract(d.value,'$.contract_hash')))))) BEGIN SELECT RAISE(ABORT,'Entry or selected variant differs from pinned inventory'); END;
97	
98	
99	-- Available graph adjacency supports bounded indexed traversal; unknown edges remain lossless in JSON.
100	CREATE TABLE device_type_edges(view_id TEXT NOT NULL,entry_id TEXT NOT NULL,type_entry_id TEXT NOT NULL,type_contract_hash TEXT NOT NULL,PRIMARY KEY(view_id,entry_id,type_entry_id),FOREIGN KEY(view_id,entry_id) REFERENCES device_view_entries ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(view_id,type_entry_id) REFERENCES device_view_entries DEFERRABLE INITIALLY DEFERRED);
101	CREATE INDEX device_type_reverse ON device_type_edges(view_id,type_entry_id);
102	CREATE TRIGGER device_edge_source BEFORE INSERT ON device_type_edges WHEN NOT EXISTS(SELECT 1 FROM device_view_entries e JOIN device_views v USING(view_id),json_each(e.dependencies_json) d WHERE e.view_id=new.view_id AND e.entry_id=new.entry_id AND e.state='available' AND v.state='staged' AND json_extract(d.value,'$.entry_id')=new.type_entry_id AND json_extract(d.value,'$.contract_hash')=new.type_contract_hash) BEGIN SELECT RAISE(ABORT,'Graph edge must match staged available membership'); END;
103	CREATE TRIGGER device_edge_project AFTER INSERT ON device_view_entries WHEN new.state='available' BEGIN INSERT INTO device_type_edges SELECT new.view_id,new.entry_id,json_extract(d.value,'$.entry_id'),json_extract(d.value,'$.contract_hash') FROM json_each(new.dependencies_json) d; END;
104	CREATE TRIGGER device_edge_update BEFORE UPDATE ON device_type_edges BEGIN SELECT RAISE(ABORT,'Graph edges are immutable'); END;
105	CREATE TRIGGER device_edge_delete BEFORE DELETE ON device_type_edges WHEN EXISTS(SELECT 1 FROM device_view_active WHERE view_id=old.view_id) OR EXISTS(SELECT 1 FROM device_view_pins WHERE view_id=old.view_id) OR ((SELECT state FROM device_views WHERE view_id=old.view_id)='sealed' AND (SELECT authorized FROM device_view_gc WHERE singleton=1) IS NOT 1) BEGIN SELECT RAISE(ABORT,'Sealed active or pinned graph edges cannot be deleted'); END;
106	
107	-- Immutable tuple identity is separate from append-only evidence acquisition.
108	CREATE TABLE wire_proof_revisions(contract_id TEXT NOT NULL REFERENCES binding_wire_contracts,revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),proof_state TEXT NOT NULL CHECK(proof_state IN ('verified','unknown','unsupported')),argument_codec_json TEXT NOT NULL CHECK(json_valid(argument_codec_json)),response_codec_json TEXT NOT NULL CHECK(json_valid(response_codec_json)),proof_source_json TEXT NOT NULL CHECK(json_valid(proof_source_json) AND json_type(proof_source_json)='object'),record_sha256 TEXT NOT NULL CHECK(length(record_sha256)=64 AND record_sha256 NOT GLOB '*[^0-9a-f]*'),PRIMARY KEY(contract_id,revision));
109	CREATE TABLE wire_proof_active(contract_id TEXT PRIMARY KEY REFERENCES binding_wire_contracts,revision INTEGER NOT NULL,FOREIGN KEY(contract_id,revision) REFERENCES wire_proof_revisions);
110	CREATE TRIGGER wire_revision_stage BEFORE INSERT ON wire_proof_revisions WHEN new.revision<>coalesce((SELECT revision FROM wire_proof_active WHERE contract_id=new.contract_id),0)+1 OR (new.proof_state='verified' AND NOT (json_type(new.argument_codec_json)='object' AND json_type(new.response_codec_json)='object' AND coalesce(json_type(new.argument_codec_json,'$.codec_id')='text' AND length(json_extract(new.argument_codec_json,'$.codec_id'))>0 AND json_extract(new.argument_codec_json,'$.schema_hash')=(SELECT schema_hash FROM binding_wire_contracts WHERE contract_id=new.contract_id),0) AND coalesce(json_type(new.response_codec_json,'$.codec_id')='text' AND length(json_extract(new.response_codec_json,'$.codec_id'))>0 AND json_extract(new.response_codec_json,'$.schema_hash')=(SELECT schema_hash FROM binding_wire_contracts WHERE contract_id=new.contract_id),0) AND coalesce(json_type(new.proof_source_json,'$.evidence')='array' AND json_array_length(new.proof_source_json,'$.evidence')>0,0))) BEGIN SELECT RAISE(ABORT,'Wire proof revision or verified evidence mismatch'); END;
111	CREATE TRIGGER wire_revision_no_update BEFORE UPDATE ON wire_proof_revisions BEGIN SELECT RAISE(ABORT,'Wire proof revisions are immutable'); END;
112	CREATE TRIGGER wire_revision_no_delete BEFORE DELETE ON wire_proof_revisions BEGIN SELECT RAISE(ABORT,'Wire proof history is retained'); END;
113	CREATE TRIGGER wire_active_initial BEFORE INSERT ON wire_proof_active WHEN new.revision<>1 BEGIN SELECT RAISE(ABORT,'Wire proof selection begins at revision1'); END;
114	CREATE TRIGGER wire_active_cas BEFORE UPDATE ON wire_proof_active WHEN new.contract_id<>old.contract_id OR new.revision<>old.revision+1 BEGIN SELECT RAISE(ABORT,'Wire proof selection requires next revision CAS'); END;
115	CREATE TRIGGER wire_active_no_delete BEFORE DELETE ON wire_proof_active BEGIN SELECT RAISE(ABORT,'Append unknown/unsupported proof to revoke rather than deleting selection'); END;
116	CREATE VIEW current_wire_proofs AS SELECT w.contract_id,w.binding_id,w.schema_hash,w.descriptor,w.interface_version,w.interface_hash,w.transaction_code,w.flags,w.oneway,coalesce(a.revision,0) AS proof_revision,coalesce(r.proof_state,w.proof_state) AS proof_state,coalesce(r.argument_codec_json,w.argument_codec_json) AS argument_codec_json,coalesce(r.response_codec_json,w.response_codec_json) AS response_codec_json,coalesce(r.proof_source_json,w.proof_source_json) AS proof_source_json,r.record_sha256 FROM binding_wire_contracts w LEFT JOIN wire_proof_active a USING(contract_id) LEFT JOIN wire_proof_revisions r ON r.contract_id=a.contract_id AND r.revision=a.revision;
117	
118	COMMIT;
119	
