1	-- Storage baseline v3: Entry1.0 base plus documented1.1 AIDL type kinds;
2	-- unknown semantic vocabulary is rejected/quarantined, never granted authority.
3	PRAGMA foreign_keys=ON;
4	BEGIN IMMEDIATE;
5	CREATE TABLE source_details(source_id TEXT NOT NULL PRIMARY KEY REFERENCES sources, document_json TEXT NOT NULL CHECK(json_valid(document_json)));
6	CREATE TABLE parse_reports(source_id TEXT NOT NULL PRIMARY KEY REFERENCES sources, document_json TEXT NOT NULL CHECK(json_valid(document_json)));
7	ALTER TABLE binding_declarations ADD COLUMN record_sha256 TEXT;
8	CREATE TABLE annotation_evidence(source_id TEXT NOT NULL REFERENCES sources, locator TEXT NOT NULL, binding_id TEXT REFERENCES bindings, scope TEXT NOT NULL, document_json TEXT NOT NULL CHECK(json_valid(document_json)), PRIMARY KEY(source_id,locator));
9	CREATE INDEX annotation_target ON annotation_evidence(binding_id);
10	CREATE TABLE permission_symbols(symbol TEXT NOT NULL, value TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources, line INTEGER NOT NULL, PRIMARY KEY(symbol,source_id,line));
11	CREATE TABLE registry_entries(registry_id TEXT NOT NULL REFERENCES registries,entry_id TEXT NOT NULL REFERENCES bindings(binding_id),document_json TEXT NOT NULL CHECK(json_valid(document_json)),record_sha256 TEXT NOT NULL CHECK(length(record_sha256)=64 AND record_sha256 NOT GLOB '*[^0-9a-f]*'),PRIMARY KEY(registry_id,entry_id));
12	CREATE TRIGGER source_details_no_update BEFORE UPDATE ON source_details BEGIN SELECT RAISE(ABORT,'Imported evidence is immutable'); END;
13	CREATE TRIGGER source_details_no_delete BEFORE DELETE ON source_details BEGIN SELECT RAISE(ABORT,'Imported evidence is immutable'); END;
14	CREATE TRIGGER annotation_evidence_no_update BEFORE UPDATE ON annotation_evidence BEGIN SELECT RAISE(ABORT,'Imported evidence is immutable'); END;
15	CREATE TRIGGER annotation_evidence_no_delete BEFORE DELETE ON annotation_evidence BEGIN SELECT RAISE(ABORT,'Imported evidence is immutable'); END;
16	CREATE TRIGGER permission_symbols_no_update BEFORE UPDATE ON permission_symbols BEGIN SELECT RAISE(ABORT,'Imported evidence is immutable'); END;
17	CREATE TRIGGER permission_symbols_no_delete BEFORE DELETE ON permission_symbols BEGIN SELECT RAISE(ABORT,'Imported evidence is immutable'); END;
18	CREATE TRIGGER registry_entries_no_update BEFORE UPDATE ON registry_entries BEGIN SELECT RAISE(ABORT,'Publish a new registry instead'); END;
19	CREATE TRIGGER registry_entries_no_delete BEFORE DELETE ON registry_entries BEGIN SELECT RAISE(ABORT,'Publish a new registry instead'); END;
20	-- ETag composition is identical for base, overlay, tombstone and history CAS.
21	CREATE TABLE catalog_view(singleton INTEGER PRIMARY KEY CHECK(singleton=1),registry_generation INTEGER NOT NULL CHECK(registry_generation>0),overlay_generation INTEGER NOT NULL CHECK(overlay_generation>=0));
22	INSERT INTO catalog_view VALUES(1,1,0);
23	CREATE TRIGGER overlay_generation_insert AFTER INSERT ON overlays BEGIN UPDATE catalog_view SET overlay_generation=overlay_generation+1; END;
24	CREATE TRIGGER overlay_generation_update AFTER UPDATE ON overlays BEGIN UPDATE catalog_view SET overlay_generation=overlay_generation+1; END;
25	CREATE TRIGGER overlay_generation_delete AFTER DELETE ON overlays BEGIN UPDATE catalog_view SET overlay_generation=overlay_generation+1; END;
26	CREATE TRIGGER registry_generation_switch AFTER UPDATE OF registry_id ON active_registry WHEN old.registry_id<>new.registry_id BEGIN UPDATE catalog_view SET registry_generation=max(registry_generation+1,(SELECT registry_version FROM registries WHERE registry_id=new.registry_id)); END;
27	CREATE TRIGGER parse_reports_no_update BEFORE UPDATE ON parse_reports BEGIN SELECT RAISE(ABORT,'Imported reports are immutable'); END;
28	CREATE TRIGGER parse_reports_no_delete BEFORE DELETE ON parse_reports BEGIN SELECT RAISE(ABORT,'Imported reports are immutable'); END;
29	CREATE TRIGGER registry_generation_initial AFTER INSERT ON active_registry BEGIN UPDATE catalog_view SET registry_generation=max(registry_generation,(SELECT registry_version FROM registries WHERE registry_id=new.registry_id)); END;
30	CREATE VIEW effective_entries AS
31	 SELECT e.entry_id,e.document_json,e.record_sha256,
32	 '"cat1:'||v.registry_generation||':'||e.record_sha256||':'||e.entry_id||':0:active"' AS etag
33	 FROM registry_entries e JOIN active_registry a ON a.registry_id=e.registry_id CROSS JOIN catalog_view v;
34	CREATE VIEW runtime_catalog AS
35	 SELECT e.entry_id,coalesce(o.document_json,e.document_json) AS document_json,
36	 '"cat1:'||v.registry_generation||':'||e.record_sha256||':'||e.entry_id||':'||coalesce(o.revision,0)||':'||coalesce(o.state,'active')||'"' AS etag
37	 FROM effective_entries e CROSS JOIN catalog_view v LEFT JOIN overlays o ON o.entry_id=e.entry_id
38	 WHERE o.entry_id IS NULL OR o.state='active'
39	 UNION ALL
40	 SELECT o.entry_id,o.document_json,'"cat1:'||v.registry_generation||':local:'||o.entry_id||':'||o.revision||':'||o.state||'"'
41	 FROM overlays o CROSS JOIN catalog_view v WHERE o.imported_binding_id IS NULL AND o.state='active' AND NOT EXISTS(SELECT 1 FROM effective_entries e WHERE e.entry_id=o.entry_id);
42	CREATE TRIGGER active_local_collision_insert BEFORE INSERT ON active_registry WHEN EXISTS(SELECT 1 FROM overlays o JOIN registry_entries e ON e.entry_id=o.entry_id AND e.registry_id=new.registry_id WHERE o.imported_binding_id IS NULL AND o.state IN ('active','deleted')) BEGIN SELECT RAISE(ABORT,'Resolve local/import collision before publication'); END;
43	CREATE TRIGGER active_local_collision_update BEFORE UPDATE OF registry_id ON active_registry WHEN EXISTS(SELECT 1 FROM overlays o JOIN registry_entries e ON e.entry_id=o.entry_id AND e.registry_id=new.registry_id WHERE o.imported_binding_id IS NULL AND o.state IN ('active','deleted')) BEGIN SELECT RAISE(ABORT,'Resolve local/import collision before publication'); END;
44	CREATE TRIGGER local_collision_insert BEFORE INSERT ON overlays WHEN new.imported_binding_id IS NULL AND new.state IN ('active','deleted') AND EXISTS(SELECT 1 FROM effective_entries e WHERE e.entry_id=new.entry_id) BEGIN SELECT RAISE(ABORT,'Use an imported overlay for an active imported identity'); END;
45	CREATE TRIGGER local_collision_update BEFORE UPDATE ON overlays WHEN new.imported_binding_id IS NULL AND new.state IN ('active','deleted') AND EXISTS(SELECT 1 FROM effective_entries e WHERE e.entry_id=new.entry_id) BEGIN SELECT RAISE(ABORT,'Use an imported overlay for an active imported identity'); END;
46	CREATE TRIGGER active_imported_base_insert BEFORE INSERT ON active_registry WHEN EXISTS(SELECT 1 FROM overlays o WHERE o.imported_binding_id IS NOT NULL AND o.state IN ('active','suppressed') AND NOT EXISTS(SELECT 1 FROM registry_entries e WHERE e.registry_id=new.registry_id AND e.entry_id=o.imported_binding_id AND e.record_sha256=o.base_record_hash)) BEGIN SELECT RAISE(ABORT,'Resolve changed or missing imported overlay base before publication'); END;
47	CREATE TRIGGER active_imported_base_update BEFORE UPDATE OF registry_id ON active_registry WHEN EXISTS(SELECT 1 FROM overlays o WHERE o.imported_binding_id IS NOT NULL AND o.state IN ('active','suppressed') AND NOT EXISTS(SELECT 1 FROM registry_entries e WHERE e.registry_id=new.registry_id AND e.entry_id=o.imported_binding_id AND e.record_sha256=o.base_record_hash)) BEGIN SELECT RAISE(ABORT,'Resolve changed or missing imported overlay base before publication'); END;
48	CREATE TRIGGER overlay_base_current_insert BEFORE INSERT ON overlays WHEN new.imported_binding_id IS NOT NULL AND new.state IN ('active','suppressed') AND NOT EXISTS(SELECT 1 FROM effective_entries e WHERE e.entry_id=new.imported_binding_id AND e.record_sha256=new.base_record_hash) BEGIN SELECT RAISE(ABORT,'Imported overlay base must match active entry'); END;
49	CREATE TRIGGER overlay_base_current_update BEFORE UPDATE ON overlays WHEN new.imported_binding_id IS NOT NULL AND new.state IN ('active','suppressed') AND NOT EXISTS(SELECT 1 FROM effective_entries e WHERE e.entry_id=new.imported_binding_id AND e.record_sha256=new.base_record_hash) BEGIN SELECT RAISE(ABORT,'Imported overlay base must match active entry'); END;
50	CREATE TABLE entry_history_reasons(entry_id TEXT NOT NULL,revision INTEGER NOT NULL,reason TEXT NOT NULL,PRIMARY KEY(entry_id,revision),FOREIGN KEY(entry_id,revision) REFERENCES entry_history(entry_id,revision));
