  "/v1/catalog/device-views/current": {
    "get": {
      "operationId": "getCurrentDeviceView",
      "description": "Read bounded current status/header and strong dv2 ETag, including generation-zero bootstrap with null header. Authorized exact profile/target only. stale forbids admission; availability is separate from permission.",
      "security": [
        {
          "catalogAuth": [
            "catalog:read"
          ]
        }
      ],
      "parameters": [
        {
          "name": "profile_id",
          "in": "query",
          "required": true,
          "schema": {
            "type": "string",
            "minLength": 1
          }
        },
        {
          "name": "target_key",
          "in": "query",
          "required": true,
          "schema": {
            "type": "string",
            "minLength": 1
          }
        }
      ],
      "responses": {
        "200": {
          "description": "Current status and bounded snapshot header; no entry collection",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/DeviceStatusResponse"
              }
            }
          },
          "headers": {
            "ETag": {
              "required": true,
              "description": "Strong scope/generation/epoch/catalog/overlay token, including null-header bootstrap. Exact composition and canonical scope hashing in API-CONTRACT.md.",
              "schema": {
                "type": "string",
                "pattern": "^\"dv2:[0-9a-f]{64}:(0|[1-9][0-9]*):(0|[1-9][0-9]*):(0|[1-9][0-9]*):(0|[1-9][0-9]*):[0-9a-f]{64}\"$"
              }
            }
          }
        },
        "403": {
          "description": "Profile/target access denied without existence disclosure"
        },
        "400": {
          "description": "Malformed bounded request or cursor"
        },
        "401": {
          "description": "Authentication required"
        }
      }
    }
  },
