  "/v1/catalog/device-views/refresh": {
    "post": {
      "operationId": "requestDeviceViewRefresh",
      "description": "Authenticated local owner only, within configured backend authority. Request bounded supported metadata refresh; never accept asserted facts, available flags, arbitrary probes or permission changes. Startup/event refresh uses the same internal coordinator. No HTTP service is implemented. After scope authorization, missing/malformed/mismatching strong current-status ETag returns428/400/412. Matched refresh atomically increments epoch and marks stale, including bootstrap; no duplicate stale token can be admitted. Exact dv2 syntax in API-CONTRACT.md.",
      "security": [
        {
          "catalogAuth": [
            "catalog:admin"
          ]
        }
      ],
      "parameters": [
        {
          "name": "If-Match",
          "in": "header",
          "required": true,
          "schema": {
            "type": "string",
            "pattern": "^\"dv2:[0-9a-f]{64}:(0|[1-9][0-9]*):(0|[1-9][0-9]*):(0|[1-9][0-9]*):(0|[1-9][0-9]*):[0-9a-f]{64}\"$"
          }
        }
      ],
      "requestBody": {
        "required": true,
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/DeviceRefreshRequest"
            }
          }
        }
      },
      "responses": {
        "202": {
          "description": "Bounded internal refresh queued; epoch incremented and previous view stale",
          "headers": {
            "ETag": {
              "required": true,
              "description": "New current-view token",
              "schema": {
                "type": "string",
                "pattern": "^\"dv2:[0-9a-f]{64}:(0|[1-9][0-9]*):(0|[1-9][0-9]*):(0|[1-9][0-9]*):(0|[1-9][0-9]*):[0-9a-f]{64}\"$"
              }
            }
          },
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/DeviceStatusResponse"
              }
            }
          }
        },
        "428": {
          "description": "Missing current-view precondition"
        },
        "412": {
          "description": "Stale view generation",
          "headers": {
            "ETag": {
              "required": true,
              "description": "Current authorized-scope view token",
              "schema": {
                "type": "string",
                "pattern": "^\"dv2:[0-9a-f]{64}:(0|[1-9][0-9]*):(0|[1-9][0-9]*):(0|[1-9][0-9]*):(0|[1-9][0-9]*):[0-9a-f]{64}\"$"
              }
            }
          }
        },
        "403": {
          "description": "Owner/backend scope denied"
        },
        "400": {
          "description": "Malformed or weak/multiple If-Match token"
        },
        "401": {
          "description": "Authentication required"
        }
      }
    }
  },
  "/v1/catalog/device-views/{view_id}/entries": {
    "get": {
      "operationId": "listDeviceViewEntries",
      "description": "Bounded rows from one immutable snapshot. Full inventory retained. Cursor binds view/profile/target/authenticated reader/filter and expires410 on invalidation; availability never grants invocation.",
