          "schema": {
            "type": "string",
            "minLength": 1
          }
        }
      ],
      "responses": {
        "200": {
          "description": "Bounded page from the pinned view",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/DeviceEntryPage"
              }
            }
          }
        },
        "410": {
          "description": "Expired/stale snapshot or cursor"
        },
        "400": {
          "description": "Malformed bounded request or cursor"
        },
        "401": {
          "description": "Authentication required"
        },
        "404": {
          "description": "Unknown or inaccessible snapshot; same disclosure rule as sibling snapshot endpoint",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/Error"
              }
            }
          }
        }
      }
    }
  }
